insert into public.therapist_resources (slug, title, kind, summary, goal, audience, duration, body_md, fields, tags, created_at)
values
  ('burnout-energy-audit', 'Burnout Energy Audit', 'worksheet'::resource_kind, 'A week of tasks sorted by what they cost and what they give back.', 'Separate exhaustion that rest will fix from exhaustion that only a change will fix.', array['Adults']::text[], '25 minutes', 'Ask for a real week, not a typical one. The useful column is the drain-to-return ratio, not the hours; clients are often surprised that the heaviest cost is a small task they resent. Use the last two prompts to open a conversation about what is negotiable, and be honest when nothing on the list is.', '[{"id": "f0", "type": "textarea", "label": "The tasks and roles that filled my week"}, {"id": "f1", "type": "textarea", "label": "For each: how much it drained me (0-10)"}, {"id": "f2", "type": "textarea", "label": "For each: how much it gave back (0-10)"}, {"id": "f3", "type": "textarea", "label": "The three worst ratios"}, {"id": "f4", "type": "textarea", "label": "Which of those I could drop, shrink or hand off"}, {"id": "f5", "type": "textarea", "label": "Which I cannot change, and what I would need to carry them"}, {"id": "f6", "type": "textarea", "label": "One recovery activity I will protect this week"}]'::jsonb, array['burnout', 'stress', 'work', 'energy']::text[], '2026-09-13T15:00:00+00:00'::timestamptz),
  ('perfectionism-cost-benefit-sheet', 'Perfectionism Cost-Benefit Sheet', 'worksheet'::resource_kind, 'Weighs what a client''s standards buy them against what the standards charge.', 'Loosen the belief that high standards are the only thing standing between the client and failure.', array['Adults', 'Teens']::text[], '20 minutes', 'Take the benefits seriously and write them down first; a client who feels their standards are being attacked will defend them. The costs usually emerge in the prompts about time, relationships and what never gets started. Close by drafting one standard at the level of good enough and agreeing to test it.', '[{"id": "f0", "type": "textarea", "label": "A standard I hold myself to"}, {"id": "f1", "type": "textarea", "label": "What it has genuinely got me"}, {"id": "f2", "type": "textarea", "label": "What it costs me in time"}, {"id": "f3", "type": "textarea", "label": "What it costs the people around me"}, {"id": "f4", "type": "textarea", "label": "Things I have not started because I could not do them perfectly"}, {"id": "f5", "type": "textarea", "label": "What good enough would look like for this standard"}, {"id": "f6", "type": "textarea", "label": "One place I will try good enough this week"}]'::jsonb, array['perfectionism', 'standards', 'self-criticism']::text[], '2026-09-13T15:00:00+00:00'::timestamptz),
  ('procrastination-loop-map', 'Procrastination Loop Map', 'worksheet'::resource_kind, 'Traces the feeling, the escape and the relief that keep a task undone.', 'Show the client that avoidance is a working loop, not a character flaw, and find its weakest link.', array['Adults', 'Teens']::text[], '20 minutes', 'Draw it as a circle in session. The relief step is the engine and most clients have never named it. Aim the intervention at the first two minutes of the task, not the whole task, and treat the plan as an experiment to report back on rather than a promise.', '[{"id": "f0", "type": "textarea", "label": "The task I keep putting off"}, {"id": "f1", "type": "textarea", "label": "What I feel when I think about starting"}, {"id": "f2", "type": "textarea", "label": "What I do instead"}, {"id": "f3", "type": "textarea", "label": "How I feel right after escaping"}, {"id": "f4", "type": "textarea", "label": "How I feel later that day"}, {"id": "f5", "type": "textarea", "label": "The smallest first step that would take under two minutes"}, {"id": "f6", "type": "textarea", "label": "When and where I will take it"}]'::jsonb, array['procrastination', 'avoidance', 'motivation']::text[], '2026-09-13T15:00:00+00:00'::timestamptz),
  ('decision-balance-sheet', 'Decision Balance Sheet', 'worksheet'::resource_kind, 'Four boxes for the gains and losses of changing and of staying the same.', 'Bring ambivalence into the open so it can be worked with instead of argued against.', array['Adults']::text[], '25 minutes', 'Fill the staying-the-same boxes as fully as the change boxes; that is what makes this different from a pep talk. Do not resolve the ambivalence for the client. Ask which box they had the most to say about, and let that be the material for the next session.', '[{"id": "f0", "type": "textarea", "label": "The change I am considering"}, {"id": "f1", "type": "textarea", "label": "Good things about staying as I am"}, {"id": "f2", "type": "textarea", "label": "Not-so-good things about staying as I am"}, {"id": "f3", "type": "textarea", "label": "Good things about making the change"}, {"id": "f4", "type": "textarea", "label": "Not-so-good things about making the change"}, {"id": "f5", "type": "textarea", "label": "On a scale of 0-10, how important is this change to me, and why not lower"}, {"id": "f6", "type": "textarea", "label": "What would move me one point up"}]'::jsonb, array['decisions', 'ambivalence', 'motivational interviewing']::text[], '2026-09-13T15:00:00+00:00'::timestamptz),
  ('session-bridge-sheet', 'Session Bridge Sheet', 'worksheet'::resource_kind, 'A short review completed before each session, linking last week to this one.', 'Make each session start from what actually happened rather than from what is loudest today.', array['Adults', 'Teens']::text[], '10 minutes', 'Send it two days before the session or have the client complete it in the waiting room. The value is in the third and fourth prompts: what got tried and what got in the way. Read it aloud together at the start and set the agenda from it.', '[{"id": "f0", "type": "textarea", "label": "What I took away from last session"}, {"id": "f1", "type": "textarea", "label": "What I tried between sessions"}, {"id": "f2", "type": "textarea", "label": "What got in the way, if anything"}, {"id": "f3", "type": "textarea", "label": "What has been on my mind this week"}, {"id": "f4", "type": "textarea", "label": "What I want to make sure we cover today"}, {"id": "f5", "type": "textarea", "label": "How I have been, 0-10"}]'::jsonb, array['between sessions', 'homework', 'session structure']::text[], '2026-09-13T15:00:00+00:00'::timestamptz),
  ('safety-behaviors-inventory', 'Safety Behaviors Inventory', 'cbt'::resource_kind, 'Lists the small things a client does to feel safer, and what each one prevents them learning.', 'Find the behaviors that keep a fear alive so they can be dropped inside exposure work.', array['Adults', 'Teens']::text[], '20 minutes', 'Clients rarely think of these as behaviors; ask what they would never do without, what they carry, who they bring, and what they check. The prediction column is where the learning happens: dropping a safety behavior only teaches something if the feared outcome was named first.', '[{"id": "f0", "type": "textarea", "label": "The situation I fear"}, {"id": "f1", "type": "textarea", "label": "Things I do or carry to get through it"}, {"id": "f2", "type": "textarea", "label": "What each one is meant to stop happening"}, {"id": "f3", "type": "textarea", "label": "What I have therefore never found out"}, {"id": "f4", "type": "textarea", "label": "The one I will drop first"}, {"id": "f5", "type": "textarea", "label": "What I predict will happen without it (0-100% sure)"}, {"id": "f6", "type": "textarea", "label": "What actually happened"}]'::jsonb, array['safety behaviors', 'anxiety', 'exposure', 'maintenance']::text[], '2026-09-13T15:00:00+00:00'::timestamptz),
  ('positive-data-log', 'Positive Data Log', 'cbt'::resource_kind, 'A running record of evidence that supports a new, kinder core belief.', 'Build a new belief by collecting what the old belief filters out.', array['Adults', 'Teens']::text[], 'Five minutes daily for several weeks', 'Word the new belief in the client''s own language before starting and keep it modest. Clients discount small evidence, so teach them to log the small stuff deliberately. Review the log in session and rate belief in both the old and the new statement each time.', '[{"id": "f0", "type": "textarea", "label": "The old belief and how much I believe it (0-100%)"}, {"id": "f1", "type": "textarea", "label": "The new belief I am testing and how much I believe it (0-100%)"}, {"id": "f2", "type": "textarea", "label": "Date"}, {"id": "f3", "type": "textarea", "label": "Something that happened that fits the new belief, however small"}, {"id": "f4", "type": "textarea", "label": "What I would normally have done with this evidence"}, {"id": "f5", "type": "textarea", "label": "Belief in the new statement now (0-100%)"}]'::jsonb, array['core beliefs', 'evidence log', 'schema', 'self-esteem']::text[], '2026-09-13T15:00:00+00:00'::timestamptz),
  ('responsibility-pie-chart', 'Responsibility Pie Chart', 'cbt'::resource_kind, 'Divides a feared or regretted outcome among every factor that contributed to it.', 'Shrink inflated responsibility by putting it on the same page as everyone and everything else involved.', array['Adults', 'Teens']::text[], '15 minutes', 'List every contributing factor before assigning any percentages, and put the client''s own slice in last; done in the other order the client claims most of the pie. Works for guilt, for OCD responsibility beliefs and for a parent blaming themselves for a child''s difficulty. Draw the actual circle.', '[{"id": "f0", "type": "textarea", "label": "What happened, or what I fear will happen"}, {"id": "f1", "type": "textarea", "label": "Everyone and everything that contributed"}, {"id": "f2", "type": "textarea", "label": "How much of the outcome belongs to each (%)"}, {"id": "f3", "type": "textarea", "label": "My slice, added last"}, {"id": "f4", "type": "textarea", "label": "How much I believed it was my fault before this (0-100%)"}, {"id": "f5", "type": "textarea", "label": "How much now"}]'::jsonb, array['guilt', 'responsibility', 'OCD', 'thinking traps']::text[], '2026-09-13T15:00:00+00:00'::timestamptz),
  ('worry-postponement-schedule', 'Worry Postponement Schedule', 'cbt'::resource_kind, 'A fixed daily worry period, with a log for the worries that arrive outside it.', 'Break the habit of worrying whenever worry shows up, and show the client that postponed worries lose their urgency.', array['Adults', 'Teens']::text[], 'One week', 'Agree on a worry period of about twenty minutes at the same time each day, not near bedtime. Everything outside it gets written down and postponed, not suppressed. Most clients report that at least half of the postponed worries have gone stale by the time the period arrives, which is the point to draw out in session.', '[{"id": "f0", "type": "textarea", "label": "My daily worry period: when and where"}, {"id": "f1", "type": "textarea", "label": "Worries that showed up outside it (write and postpone)"}, {"id": "f2", "type": "textarea", "label": "At the worry period: which still mattered"}, {"id": "f3", "type": "textarea", "label": "Which had gone stale"}, {"id": "f4", "type": "textarea", "label": "What I did during the worry period with the ones that mattered"}, {"id": "f5", "type": "textarea", "label": "How hard was postponing today (0-10)"}]'::jsonb, array['worry', 'GAD', 'stimulus control']::text[], '2026-09-13T15:00:00+00:00'::timestamptz),
  ('reassurance-seeking-log', 'Reassurance Seeking Log', 'cbt'::resource_kind, 'Tracks every request for reassurance, what it relieved and how long that lasted.', 'Make the short half-life of reassurance visible, and plan how to tolerate the doubt instead.', array['Adults', 'Teens']::text[], 'One week', 'Include the quiet forms: checking online, rereading a message, asking the same question a different way. The duration column does the work. Involve partners or parents in what they will say instead of answering, and agree the wording in session so it does not sound like a rejection.', '[{"id": "f0", "type": "textarea", "label": "Date and time"}, {"id": "f1", "type": "textarea", "label": "What I was worried about"}, {"id": "f2", "type": "textarea", "label": "Who or what I asked, and how"}, {"id": "f3", "type": "textarea", "label": "Relief straight after (0-10)"}, {"id": "f4", "type": "textarea", "label": "How long the relief lasted"}, {"id": "f5", "type": "textarea", "label": "What I could have done with the doubt instead"}, {"id": "f6", "type": "textarea", "label": "What the people around me will say next time instead of reassuring"}]'::jsonb, array['reassurance', 'health anxiety', 'OCD', 'anxiety']::text[], '2026-09-13T15:00:00+00:00'::timestamptz),
  ('thank-your-mind-practice', 'Thank Your Mind Practice', 'act'::resource_kind, 'A defusion habit of noticing a sticky thought and thanking the mind for it.', 'Change the client''s relationship with a thought without arguing with its content.', array['Adults', 'Teens']::text[], '5 minutes to teach, then in the moment', 'Model it with one of your own thoughts first so it does not sound like sarcasm. The tone is warm, as toward an over-helpful friend. Follow with the question of what the mind is trying to protect; clients find it easier to unhook from a thought once they can see its job.', '[{"id": "f0", "type": "textarea", "label": "The thought my mind keeps offering"}, {"id": "f1", "type": "textarea", "label": "What my mind might be trying to protect me from"}, {"id": "f2", "type": "textarea", "label": "The thank-you I will use (in my own words)"}, {"id": "f3", "type": "textarea", "label": "When I tried it this week"}, {"id": "f4", "type": "textarea", "label": "What changed, even slightly"}]'::jsonb, array['defusion', 'thoughts', 'core ACT']::text[], '2026-09-13T15:00:00+00:00'::timestamptz),
  ('choice-point-map', 'Choice Point Map', 'act'::resource_kind, 'A one-page map of a difficult situation, the hooks it brings and the toward and away moves available.', 'Give the client a single picture of the moment of choice they meet again and again.', array['Adults', 'Teens', 'Groups']::text[], '20 minutes', 'Draw the fork in session. Be strict that away moves are defined by their function, not by what they look like; scrolling can be a toward move if it is a chosen rest. Fill the toward side with things the client has done before, not ideals, and ask which skill from the toolkit helps at the fork.', '[{"id": "f0", "type": "textarea", "label": "The situation I keep meeting"}, {"id": "f1", "type": "textarea", "label": "The thoughts and feelings that show up (the hooks)"}, {"id": "f2", "type": "textarea", "label": "My usual away moves"}, {"id": "f3", "type": "textarea", "label": "What those away moves cost me"}, {"id": "f4", "type": "textarea", "label": "Toward moves I have made before in this situation"}, {"id": "f5", "type": "textarea", "label": "The values behind the toward moves"}, {"id": "f6", "type": "textarea", "label": "The skill I will use at the fork next time"}]'::jsonb, array['choice point', 'values', 'committed action']::text[], '2026-09-13T15:00:00+00:00'::timestamptz),
  ('struggle-switch-dial', 'Struggle Switch Dial', 'act'::resource_kind, 'Rates how hard the client is fighting a feeling, separately from how strong the feeling is.', 'Show the client that the struggle, not the feeling, is what they can turn down.', array['Adults', 'Teens']::text[], '15 minutes', 'Introduce the two dials with a recent example where a feeling was tolerable and one where it was not; the difference is usually the second dial. Practice turning the struggle dial down in session with a mild discomfort before asking the client to try it with anxiety.', '[{"id": "f0", "type": "textarea", "label": "A feeling I have been fighting"}, {"id": "f1", "type": "textarea", "label": "How strong it has been (0-10)"}, {"id": "f2", "type": "textarea", "label": "How hard I have been fighting it (0-10)"}, {"id": "f3", "type": "textarea", "label": "What fighting it looks like for me"}, {"id": "f4", "type": "textarea", "label": "What happened to the feeling when I fought it"}, {"id": "f5", "type": "textarea", "label": "What I noticed when I let the fight dial drop, even by one"}]'::jsonb, array['acceptance', 'struggle switch', 'anxiety', 'willingness']::text[], '2026-09-13T15:00:00+00:00'::timestamptz),
  ('values-bullseye', 'Values Bullseye', 'act'::resource_kind, 'A dartboard with four life areas, marked with how close the client is living to each value.', 'Get a quick, visual reading of the gap between values and daily life in four domains.', array['Adults', 'Teens']::text[], '20 minutes', 'Have the client write one sentence of value for each quadrant before placing any marks, or the marks become a mood rating. It repeats well every few sessions as a progress measure. Ask about the barriers only for the quadrant with the widest gap.', '[{"id": "f0", "type": "textarea", "label": "Work and education: what matters to me here"}, {"id": "f1", "type": "textarea", "label": "Leisure: what matters to me here"}, {"id": "f2", "type": "textarea", "label": "Relationships: what matters to me here"}, {"id": "f3", "type": "textarea", "label": "Personal growth and health: what matters to me here"}, {"id": "f4", "type": "textarea", "label": "For each: how close to the center am I living (1 = far, 7 = bullseye)"}, {"id": "f5", "type": "textarea", "label": "What stands between me and the center in the widest gap"}, {"id": "f6", "type": "textarea", "label": "One move toward the center this week"}]'::jsonb, array['values', 'bullseye', 'assessment']::text[], '2026-09-13T15:00:00+00:00'::timestamptz),
  ('im-having-the-thought-that', 'I''m Having the Thought That', 'act'::resource_kind, 'A three-step language practice that puts distance between the client and a thought.', 'Teach the client to hear a thought as a thought rather than as a fact.', array['Adults', 'Teens', 'Groups']::text[], '10 minutes', 'Run all three steps out loud in session: the bare thought, then with I am having the thought that, then with I notice I am having the thought that. Ask what changed in the body at each step. Pick a thought with real charge but not the most painful one on the first pass.', '[{"id": "f0", "type": "textarea", "label": "The thought, as it usually arrives"}, {"id": "f1", "type": "textarea", "label": "I''m having the thought that..."}, {"id": "f2", "type": "textarea", "label": "I notice I''m having the thought that..."}, {"id": "f3", "type": "textarea", "label": "What shifted between the first and last version"}, {"id": "f4", "type": "textarea", "label": "Where I will use this during the week"}]'::jsonb, array['defusion', 'language', 'core ACT']::text[], '2026-09-13T15:00:00+00:00'::timestamptz),
  ('give-skills-planner', 'GIVE Skills Planner', 'dbt'::resource_kind, 'Prepares a conversation where the relationship matters more than the outcome.', 'Help the client ask or refuse in a way the relationship survives.', array['Adults', 'Teens', 'Groups']::text[], '20 minutes', 'Pair it with DEAR MAN: that script says what to say, this one says how. Gentle, Interested, Validate, Easy manner. Role-play the validation line; clients often write a validation that is actually a concession. The manner column is best rehearsed with a timer, since easy manner disappears under pressure.', '[{"id": "f0", "type": "textarea", "label": "The conversation, and why the relationship matters here"}, {"id": "f1", "type": "textarea", "label": "Gentle: what I will not do (attacks, threats, judging, eye-rolling)"}, {"id": "f2", "type": "textarea", "label": "Interested: the question I will ask them, and how I will listen"}, {"id": "f3", "type": "textarea", "label": "Validate: what I can honestly acknowledge about their position"}, {"id": "f4", "type": "textarea", "label": "Easy manner: how I will keep it light"}, {"id": "f5", "type": "textarea", "label": "How it went, and what I would keep"}]'::jsonb, array['interpersonal effectiveness', 'GIVE', 'relationships']::text[], '2026-09-13T15:00:00+00:00'::timestamptz),
  ('fast-self-respect-check', 'FAST Self-Respect Check', 'dbt'::resource_kind, 'A review of a recent interaction against the four self-respect skills.', 'Help the client hold their own values in an interaction instead of trading them for approval.', array['Adults', 'Teens']::text[], '15 minutes', 'Fair, no Apologies, Stick to values, Truthful. The over-apologizing prompt is the one most clients recognize immediately. Use a real recent interaction and be specific about what the extra apology or the small lie bought. Plan the next interaction with the values line written in advance.', '[{"id": "f0", "type": "textarea", "label": "A recent interaction where I lost some self-respect"}, {"id": "f1", "type": "textarea", "label": "Fair: was I fair to myself as well as to them"}, {"id": "f2", "type": "textarea", "label": "No apologies: what I apologized for that needed no apology"}, {"id": "f3", "type": "textarea", "label": "Stick to values: where I gave ground I did not want to give"}, {"id": "f4", "type": "textarea", "label": "Truthful: what I said that was not quite true, and why"}, {"id": "f5", "type": "textarea", "label": "What I will do differently next time"}]'::jsonb, array['interpersonal effectiveness', 'FAST', 'self-respect']::text[], '2026-09-13T15:00:00+00:00'::timestamptz),
  ('please-skills-tracker', 'PLEASE Skills Tracker', 'dbt'::resource_kind, 'A daily check on the physical basics that make emotions harder or easier to regulate.', 'Reduce emotional vulnerability by attending to illness, eating, substances, sleep and exercise.', array['Adults', 'Teens']::text[], 'Two minutes daily for a week', 'Frame this as lowering the water line, not fixing the emotions. Look for the pattern across the week rather than any single day; the link between a bad night and the next afternoon''s blow-up is usually the finding. Keep the exercise bar low, and never turn the eating prompt into a diet.', '[{"id": "f0", "type": "textarea", "label": "Date"}, {"id": "f1", "type": "textarea", "label": "Physical illness: anything I am ignoring or not treating"}, {"id": "f2", "type": "textarea", "label": "Eating: did I eat regularly and enough today"}, {"id": "f3", "type": "textarea", "label": "Mood-altering substances: what I used, including caffeine and alcohol"}, {"id": "f4", "type": "textarea", "label": "Sleep: hours, and quality (0-10)"}, {"id": "f5", "type": "textarea", "label": "Exercise: any movement today"}, {"id": "f6", "type": "textarea", "label": "My emotional vulnerability today (0-10) and what I notice"}]'::jsonb, array['emotion regulation', 'PLEASE', 'vulnerability', 'sleep']::text[], '2026-09-13T15:00:00+00:00'::timestamptz),
  ('urge-pros-and-cons-grid', 'Urge Pros and Cons Grid', 'dbt'::resource_kind, 'Four boxes weighing acting on a crisis urge against tolerating it, filled in ahead of time.', 'Give the client a completed grid to read in the moment, when they cannot think one up.', array['Adults', 'Teens']::text[], '25 minutes', 'Complete it in session while calm, and make the pros of acting on the urge honest; a grid that pretends there is no upside will be ignored at 2 a.m. Add the long-term column explicitly. Have the client photograph it and decide where it lives on their phone.', '[{"id": "f0", "type": "textarea", "label": "The urge this grid is for"}, {"id": "f1", "type": "textarea", "label": "Pros of acting on the urge (be honest)"}, {"id": "f2", "type": "textarea", "label": "Cons of acting on the urge, short term and long term"}, {"id": "f3", "type": "textarea", "label": "Pros of tolerating the urge, short term and long term"}, {"id": "f4", "type": "textarea", "label": "Cons of tolerating the urge"}, {"id": "f5", "type": "textarea", "label": "What I will read first when the urge is at its strongest"}, {"id": "f6", "type": "textarea", "label": "Where this grid lives so I can find it"}]'::jsonb, array['distress tolerance', 'urges', 'pros and cons', 'crisis']::text[], '2026-09-13T15:00:00+00:00'::timestamptz),
  ('check-the-facts', 'Check the Facts', 'dbt'::resource_kind, 'Tests whether an emotion fits the facts of the event, and whether its size fits.', 'Decide whether an emotion should be acted on, problem-solved or changed with opposite action.', array['Adults', 'Teens']::text[], '20 minutes', 'Keep the event description free of interpretation; that step alone often shifts the emotion. The threat prompt is where catastrophizing shows up, so ask for the probability out loud. If the emotion fits the facts, move to problem solving rather than opposite action, and say so plainly.', '[{"id": "f0", "type": "textarea", "label": "The emotion, and its intensity (0-100)"}, {"id": "f1", "type": "textarea", "label": "The event that prompted it: only what a camera would have recorded"}, {"id": "f2", "type": "textarea", "label": "My interpretations and assumptions about the event"}, {"id": "f3", "type": "textarea", "label": "Other ways of seeing it"}, {"id": "f4", "type": "textarea", "label": "Am I assuming a threat? How likely is it, really (0-100%)"}, {"id": "f5", "type": "textarea", "label": "If the worst happened, how would I cope"}, {"id": "f6", "type": "textarea", "label": "Does the emotion fit the facts? Does its size? What I will do next"}]'::jsonb, array['emotion regulation', 'check the facts', 'interpretation']::text[], '2026-09-13T15:00:00+00:00'::timestamptz),
  ('four-horsemen-spotter', 'Four Horsemen Spotter', 'couples'::resource_kind, 'Each partner identifies their own criticism, contempt, defensiveness and stonewalling, and the antidote for each.', 'Give a couple a shared, low-blame vocabulary for what goes wrong in their arguments.', array['Couples']::text[], '30 minutes', 'Each partner completes it about themselves only, never about the other; enforce that gently, since the temptation is strong. Contempt deserves the most time and the most care. Finish with each partner choosing one antidote to practice and telling the other what it will sound like.', '[{"id": "f0", "type": "textarea", "label": "Criticism: how it sounds when I do it"}, {"id": "f1", "type": "textarea", "label": "Contempt: how it shows up in me (tone, face, jokes)"}, {"id": "f2", "type": "textarea", "label": "Defensiveness: my usual counterattack or excuse"}, {"id": "f3", "type": "textarea", "label": "Stonewalling: what shutting down looks like for me, and what I need to come back"}, {"id": "f4", "type": "textarea", "label": "The horseman I ride most"}, {"id": "f5", "type": "textarea", "label": "The antidote I will practice (gentle start-up, appreciation, taking responsibility, self-soothing)"}, {"id": "f6", "type": "textarea", "label": "What my partner will hear when I get it right"}]'::jsonb, array['Gottman', 'four horsemen', 'conflict']::text[], '2026-09-13T15:00:00+00:00'::timestamptz),
  ('stress-reducing-conversation-guide', 'Stress-Reducing Conversation Guide', 'couples'::resource_kind, 'A structured daily conversation about stress from outside the relationship.', 'Teach a couple to support each other about outside stress without turning it into a fight about the relationship.', array['Couples']::text[], '20 minutes daily', 'The rule is that the stress must come from outside the relationship. Teach the listener role in session: understanding before advice, taking the partner''s side, no problem solving unless asked. Most couples need the listener prompts on paper for the first two weeks.', '[{"id": "f0", "type": "textarea", "label": "Speaker: what is stressing me outside our relationship"}, {"id": "f1", "type": "textarea", "label": "Listener: what I heard, in my own words"}, {"id": "f2", "type": "textarea", "label": "Listener: what I said to take their side"}, {"id": "f3", "type": "textarea", "label": "Listener: did I offer advice? Was it asked for?"}, {"id": "f4", "type": "textarea", "label": "Speaker: what I needed from the conversation, and whether I got it"}, {"id": "f5", "type": "textarea", "label": "One thing we will change about how we did this"}]'::jsonb, array['Gottman', 'listening', 'support', 'stress']::text[], '2026-09-13T15:00:00+00:00'::timestamptz),
  ('dreams-within-conflict', 'Dreams Within Conflict', 'couples'::resource_kind, 'An interview for a gridlocked issue, uncovering the hope or history underneath each position.', 'Turn a perpetual, stuck argument into a conversation about what each partner is protecting.', array['Couples']::text[], 'Full session', 'Only for gridlocked issues, not solvable ones. Each partner interviews the other for about ten minutes and may not persuade, correct or interrupt; you hold that boundary. The questions about childhood and about what the position means to them are the ones that open things up. Do not aim for a solution in this session.', '[{"id": "f0", "type": "textarea", "label": "The issue we cannot get past"}, {"id": "f1", "type": "textarea", "label": "My position on it"}, {"id": "f2", "type": "textarea", "label": "What this position means to me, and where it comes from"}, {"id": "f3", "type": "textarea", "label": "What I am afraid would happen if I gave it up"}, {"id": "f4", "type": "textarea", "label": "The dream or value underneath my position"}, {"id": "f5", "type": "textarea", "label": "What I learned about my partner''s dream"}, {"id": "f6", "type": "textarea", "label": "What parts of this I could be flexible on, and what I cannot"}]'::jsonb, array['Gottman', 'gridlock', 'meaning', 'conflict']::text[], '2026-09-13T15:00:00+00:00'::timestamptz),
  ('aftermath-of-a-fight-debrief', 'Aftermath of a Fight Debrief', 'couples'::resource_kind, 'A five-step structured conversation for processing a fight after both partners are calm.', 'Let a couple learn from a regrettable incident without reopening it.', array['Couples']::text[], '45 minutes', 'Wait at least a day and check both partners are calm before starting. Each partner describes their own reality of the fight without interruption, and the other summarizes it back before adding their own. Triggers from past history are the richest step and the one to slow down on. End with one concrete change each.', '[{"id": "f0", "type": "textarea", "label": "How I felt during the fight (name feelings, not their behavior)"}, {"id": "f1", "type": "textarea", "label": "My reality of what happened"}, {"id": "f2", "type": "textarea", "label": "My partner''s reality, as I understood it"}, {"id": "f3", "type": "textarea", "label": "What this fight triggered from my past"}, {"id": "f4", "type": "textarea", "label": "My part in it, and what I take responsibility for"}, {"id": "f5", "type": "textarea", "label": "One thing I will do differently next time"}, {"id": "f6", "type": "textarea", "label": "One thing I need from my partner next time"}]'::jsonb, array['repair', 'processing', 'conflict', 'Gottman']::text[], '2026-09-13T15:00:00+00:00'::timestamptz),
  ('raw-spots-and-reaching', 'Raw Spots and Reaching', 'couples'::resource_kind, 'Each partner names their attachment raw spots and what a reach for the other would look like.', 'Move a couple from protest and withdrawal toward direct, softer reaching.', array['Couples']::text[], 'Full session', 'Belongs in the middle of EFT work, after the cycle has been mapped. Slow down on the raw-spot prompts and stay with the softer emotion under the protest. The reaching prompt should be written in the second person and spoken to the partner in session, with you keeping the other partner receptive.', '[{"id": "f0", "type": "textarea", "label": "The raw spot that gets touched most in our cycle"}, {"id": "f1", "type": "textarea", "label": "What I do when it gets touched (protest, pursue, withdraw, shut down)"}, {"id": "f2", "type": "textarea", "label": "The softer feeling underneath that move"}, {"id": "f3", "type": "textarea", "label": "What I fear my partner would think if they saw that feeling"}, {"id": "f4", "type": "textarea", "label": "What I actually need from my partner in that moment"}, {"id": "f5", "type": "textarea", "label": "How I would say it to them directly, in my own words"}, {"id": "f6", "type": "textarea", "label": "What I need to hear back"}]'::jsonb, array['EFT', 'attachment', 'cycle']::text[], '2026-09-13T15:00:00+00:00'::timestamptz),
  ('worry-time-box', 'Worry Time Box', 'kids'::resource_kind, 'A decorated box where a child posts written worries to be opened at a set time with a parent.', 'Contain worry to one part of the day, with a parent as the reliable listener.', array['Children', 'Teens']::text[], '20 minutes to make, then daily', 'Let the child decorate the box; ownership matters. Agree the worry time with the parent and keep it short and not at bedtime. Coach the parent to open the box with curiosity and without fixing, and to notice with the child which worries have gone quiet by the time they are read.', '[{"id": "f0", "type": "textarea", "label": "My worry box looks like"}, {"id": "f1", "type": "textarea", "label": "Our worry time is (when and with whom)"}, {"id": "f2", "type": "textarea", "label": "Worries I posted this week"}, {"id": "f3", "type": "textarea", "label": "Worries that did not seem as big when we opened the box"}, {"id": "f4", "type": "textarea", "label": "Worries that still needed help"}, {"id": "f5", "type": "textarea", "label": "What my grown-up said that helped"}]'::jsonb, array['worry', 'anxiety', 'children', 'parenting']::text[], '2026-09-13T15:00:00+00:00'::timestamptz),
  ('anger-volcano-map', 'Anger Volcano Map', 'kids'::resource_kind, 'A volcano drawing that shows a child''s anger rising from rumbles to eruption.', 'Help a child notice anger early and choose a cooling step before the top.', array['Children']::text[], '25 minutes', 'Draw a big volcano and let the child fill in the levels in their own words. The rumble level is what to spend time on; children usually only know the eruption. Practice one cooling step in session and make sure a parent or teacher knows the child''s rumble signs.', '[{"id": "f0", "type": "textarea", "label": "Things that make my lava start to bubble"}, {"id": "f1", "type": "textarea", "label": "Rumbles: how my body tells me it is starting"}, {"id": "f2", "type": "textarea", "label": "Getting hot: what I do and say when it grows"}, {"id": "f3", "type": "textarea", "label": "Eruption: what happens at the top"}, {"id": "f4", "type": "textarea", "label": "My cool-down move at rumble level"}, {"id": "f5", "type": "textarea", "label": "My cool-down move at getting hot"}, {"id": "f6", "type": "textarea", "label": "A grown-up who can spot my rumbles"}]'::jsonb, array['anger', 'children', 'triggers', 'regulation']::text[], '2026-09-13T15:00:00+00:00'::timestamptz),
  ('belly-breathing-buddy', 'Belly Breathing Buddy', 'kids'::resource_kind, 'Slow breathing practice with a small stuffed toy riding on the child''s stomach.', 'Teach diaphragmatic breathing to a child through play rather than instruction.', array['Children']::text[], '10 minutes', 'Lying down, toy on the belly, the job is to rock the buddy to sleep slowly. Count the breaths out loud together at first, breathing out longer than in. Do it when the child is calm so it is available when they are not; a skill taught mid-meltdown does not stick.', '[{"id": "f0", "type": "textarea", "label": "My breathing buddy''s name"}, {"id": "f1", "type": "textarea", "label": "How my buddy moves when I breathe slowly"}, {"id": "f2", "type": "textarea", "label": "When I practiced this week"}, {"id": "f3", "type": "textarea", "label": "A time I used it when I felt wobbly"}, {"id": "f4", "type": "textarea", "label": "How my body felt after"}]'::jsonb, array['breathing', 'regulation', 'children', 'self-soothing']::text[], '2026-09-13T15:00:00+00:00'::timestamptz),
  ('bedtime-routine-builder', 'Bedtime Routine Builder', 'kids'::resource_kind, 'A picture-and-words plan for the last hour before sleep, built with the child.', 'Give a child a predictable wind-down that a parent can hold consistently.', array['Children', 'Adults']::text[], '25 minutes', 'Build it with the child and the parent in the room. Keep it to five or six steps in the same order every night, with screens finished before it begins. The prompt about what happens when the child gets up again is the one parents most need agreed in advance, in a calm, boring script.', '[{"id": "f0", "type": "textarea", "label": "Our bedtime is"}, {"id": "f1", "type": "textarea", "label": "Step 1 (screens are off)"}, {"id": "f2", "type": "textarea", "label": "Step 2"}, {"id": "f3", "type": "textarea", "label": "Step 3"}, {"id": "f4", "type": "textarea", "label": "Step 4"}, {"id": "f5", "type": "textarea", "label": "Step 5: lights out words we always say"}, {"id": "f6", "type": "textarea", "label": "What my grown-up will do if I get up again"}, {"id": "f7", "type": "textarea", "label": "How the first week went"}]'::jsonb, array['sleep', 'routines', 'children', 'parenting']::text[], '2026-09-13T15:00:00+00:00'::timestamptz),
  ('parent-coaching-sheet-special-time', 'Parent Coaching Sheet: Special Time', 'kids'::resource_kind, 'Five minutes a day of child-led play where the parent follows, describes and praises.', 'Strengthen the parent-child relationship so that limits later carry more weight.', array['Adults']::text[], '15 minutes to teach, then five minutes daily', 'Teach the parent to describe what the child is doing, reflect what the child says and praise specifics, and to avoid questions, commands and criticism during the five minutes. Rehearse it in session with the parent playing while you describe. The log prompt about what was hardest to hold back is where coaching happens.', '[{"id": "f0", "type": "textarea", "label": "When special time will happen each day"}, {"id": "f1", "type": "textarea", "label": "Toys or activities that work for following the child''s lead"}, {"id": "f2", "type": "textarea", "label": "Date and what we played"}, {"id": "f3", "type": "textarea", "label": "Things I described and praised"}, {"id": "f4", "type": "textarea", "label": "What I found hardest to hold back (questions, commands, corrections)"}, {"id": "f5", "type": "textarea", "label": "How my child responded"}, {"id": "f6", "type": "textarea", "label": "What I noticed in the rest of the day"}]'::jsonb, array['parenting', 'PCIT', 'connection', 'play']::text[], '2026-09-13T15:00:00+00:00'::timestamptz),
  ('feelings-bingo', 'Feelings Bingo', 'game'::resource_kind, 'Bingo cards of feeling words, marked when a player shares a time they felt each one.', 'Build emotion vocabulary and easy disclosure in a group or family.', array['Children', 'Teens', 'Groups']::text[], '20 minutes', 'Make the cards from a word bank the group builds first, so every card has feelings they actually know. A square is marked only after a short real example. Mix mild feelings with big ones and let players skip a square twice. Play a second round with body sensations instead of words if the group is ready.', '[{"id": "f0", "type": "textarea", "label": "Feeling words we put on our cards"}, {"id": "f1", "type": "textarea", "label": "The squares I marked, with my examples"}, {"id": "f2", "type": "textarea", "label": "A feeling word that was new to me"}, {"id": "f3", "type": "textarea", "label": "A feeling I heard someone else describe that I have had too"}, {"id": "f4", "type": "textarea", "label": "A square I skipped, and why"}]'::jsonb, array['emotion recognition', 'play', 'group', 'children']::text[], '2026-09-13T15:00:00+00:00'::timestamptz),
  ('would-you-rather-coping-edition', 'Would You Rather: Coping Edition', 'game'::resource_kind, 'Pairs of coping choices, argued for and against by the group before anyone votes.', 'Get a group talking about what helps and what backfires without anyone having to own a struggle.', array['Teens', 'Adults', 'Groups']::text[], '20 minutes', 'Write the pairs so neither option is obviously right: call a friend or go for a run, cry it out or distract, tell someone or wait a day. Everyone argues both sides before voting. The debrief prompt about which choices depend on the situation is where the group''s coping wisdom comes out.', '[{"id": "f0", "type": "textarea", "label": "The pairs we used"}, {"id": "f1", "type": "textarea", "label": "My picks and my reasons"}, {"id": "f2", "type": "textarea", "label": "A pick where I was in the minority"}, {"id": "f3", "type": "textarea", "label": "Which choices depend on the situation"}, {"id": "f4", "type": "textarea", "label": "A coping option I had not considered before"}]'::jsonb, array['coping skills', 'play', 'group']::text[], '2026-09-13T15:00:00+00:00'::timestamptz),
  ('thought-detective', 'Thought Detective', 'game'::resource_kind, 'Players investigate a suspect thought by gathering clues for and against it.', 'Make evidence-checking feel like a case to solve rather than a form to fill in.', array['Children', 'Teens']::text[], '25 minutes', 'Give the child a notebook and a magnifying glass if you have one. The thought is the suspect, and the child collects clues that support it and clues that do not, then delivers a verdict. Play it first with a thought that is clearly untrue to teach the moves, then with one of their own.', '[{"id": "f0", "type": "textarea", "label": "The suspect thought"}, {"id": "f1", "type": "textarea", "label": "Clues that say it is true"}, {"id": "f2", "type": "textarea", "label": "Clues that say it is not true"}, {"id": "f3", "type": "textarea", "label": "Clues I had to go and look for"}, {"id": "f4", "type": "textarea", "label": "The detective''s verdict: true, not true, or only partly true"}, {"id": "f5", "type": "textarea", "label": "A fairer thought, based on all the clues"}]'::jsonb, array['thinking traps', 'play', 'children', 'evidence']::text[], '2026-09-13T15:00:00+00:00'::timestamptz),
  ('compliment-toss', 'Compliment Toss', 'game'::resource_kind, 'A soft ball thrown around the circle; the thrower gives a specific compliment to the catcher.', 'Practice giving and receiving specific praise in a group, with the awkwardness built in.', array['Children', 'Teens', 'Groups']::text[], '15 minutes', 'Compliments must be specific and about something the person did or said in the group, not their appearance. Model the first one. Receiving is half the game: the catcher says thank you and nothing else, and the leader stops any deflecting. Ask afterward which was harder, giving or getting.', '[{"id": "f0", "type": "textarea", "label": "A compliment I gave"}, {"id": "f1", "type": "textarea", "label": "A compliment I got"}, {"id": "f2", "type": "textarea", "label": "What I wanted to say instead of thank you"}, {"id": "f3", "type": "textarea", "label": "Which was harder, giving or receiving"}, {"id": "f4", "type": "textarea", "label": "Something I noticed about someone that I did not get to say"}]'::jsonb, array['self-esteem', 'group', 'play', 'communication']::text[], '2026-09-13T15:00:00+00:00'::timestamptz),
  ('emotion-dice', 'Emotion Dice', 'game'::resource_kind, 'One die names a feeling and one names a prompt; players answer the combination they roll.', 'Lower the stakes of talking about feelings by leaving the choice of feeling to chance.', array['Children', 'Teens', 'Groups']::text[], '20 minutes', 'Label one die with feelings and one with prompts such as a time I felt this, what my body does, what helps, who I would tell. Chance removes the sense of being singled out. Keep two passes per player, and take your own turns so the group sees an adult answer plainly.', '[{"id": "f0", "type": "textarea", "label": "Feelings on our die"}, {"id": "f1", "type": "textarea", "label": "Prompts on our other die"}, {"id": "f2", "type": "textarea", "label": "The combinations I rolled and what I said"}, {"id": "f3", "type": "textarea", "label": "A combination someone else rolled that I could have answered too"}, {"id": "f4", "type": "textarea", "label": "The roll I passed on"}]'::jsonb, array['emotion identification', 'play', 'disclosure', 'group']::text[], '2026-09-13T15:00:00+00:00'::timestamptz)
